function run(selected_text) {
  let value;
  try {
    value = JSON.parse(selected_text);
  } catch (error) {
    throw new Error("Invalid JSON: " + error.message);
  }

  const kind = value === null ? "null" : Array.isArray(value) ? "array" : typeof value;
  return "Valid JSON — " + kind + ".";
}
